package com.furryfemboy.registry;
import com.furryfemboy.FurryFemboyMod; import com.furryfemboy.entity.FurryFemboyEntity; import net.minecraft.world.entity.SpawnPlacements; import net.minecraft.world.entity.Mob; import net.minecraft.world.entity.MobCategory; import net.minecraft.world.level.levelgen.Heightmap; import net.minecraftforge.event.entity.SpawnPlacementRegisterEvent; import net.minecraftforge.event.entity.EntityAttributeCreationEvent; import net.minecraftforge.eventbus.api.SubscribeEvent; import net.minecraftforge.fml.common.Mod;
@Mod.EventBusSubscriber(modid=FurryFemboyMod.MOD_ID,bus=Mod.EventBusSubscriber.Bus.MOD)
public final class ModEvents { @SubscribeEvent public static void attributes(EntityAttributeCreationEvent e){e.put(ModEntities.FURRY_FEMBOY.get(),FurryFemboyEntity.createAttributes().build());} @SubscribeEvent public static void placements(SpawnPlacementRegisterEvent e){e.register(ModEntities.FURRY_FEMBOY.get(),SpawnPlacements.Type.ON_GROUND,Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,FurryFemboyEntity::checkFurrySpawn,SpawnPlacementRegisterEvent.Operation.REPLACE);} }
